<?php
declare(strict_types=1);
require_once __DIR__.'/dashboard-profile.php';
function need(bool $condition,string $message):void {if(!$condition)throw new RuntimeException($message);}
function fixture():PDO {$class=class_exists('DashboardPDO')?DashboardPDO::class:PDO::class;$dsn=getenv('CLASSROOM_DSN')?:'sqlite::memory:';if($dsn!=='sqlite::memory:'&&!preg_match('/^mysql:host=127\.0\.0\.1;port=\d+;dbname=classroom_perf_test$/D',$dsn))throw new RuntimeException('Owned fixture required');return new $class($dsn,$dsn==='sqlite::memory:'?null:'root',null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_EMULATE_PREPARES=>false,PDO::ATTR_STATEMENT_CLASS=>[DashboardStatement::class]]);}
function lastRecord():array {need(count(DashboardProfile::$queries)>0,'SQL attempt was not recorded');return DashboardProfile::$queries[array_key_last(DashboardProfile::$queries)];}
function binding(array $row,int|string $parameter,mixed $value,int $type):void {$found=array_values(array_filter($row['bindings']??[],fn($b)=>$b['parameter']===$parameter));need(count($found)===1,'Actual binding missing: '.(string)$parameter);need($found[0]['value']===$value,'Wrong execution-time value');need($found[0]['pdo_type']===$type,'Wrong PDO parameter type');}
$cases=[
 'bindValue_snapshot'=>function(){ $d=fixture();$s=$d->prepare('SELECT :value');$v='alpha';$s->bindValue(':value',$v,PDO::PARAM_STR);$v='beta';$s->execute();need($s->fetchColumn()==='alpha','bindValue behavior changed');binding(lastRecord(),':value','alpha',PDO::PARAM_STR);},
 'bindParam_repeated_reference'=>function(){ $d=fixture();$s=$d->prepare('SELECT :value');$v=17;$s->bindParam('value',$v,PDO::PARAM_INT);$s->execute();need((int)$s->fetchColumn()===17,'First reference execution');$first=lastRecord();$v=29;$s->execute();need((int)$s->fetchColumn()===29,'Changed reference execution');binding($first,':value',17,PDO::PARAM_INT);binding(lastRecord(),':value',29,PDO::PARAM_INT);},
 'execute_array_and_reuse'=>function(){ $d=fixture();$s=$d->prepare('SELECT :value');$s->execute(['value'=>'array']);need($s->fetchColumn()==='array','execute array behavior');binding(lastRecord(),':value','array',PDO::PARAM_STR);$s->execute();need($s->fetchColumn()==='array','Array binding not retained');binding(lastRecord(),':value','array',PDO::PARAM_STR);},
 'positional_bindings'=>function(){ $d=fixture();$s=$d->prepare('SELECT ?,?');$s->bindValue(1,7,PDO::PARAM_INT);$s->bindValue(2,null,PDO::PARAM_NULL);$s->execute();need($s->fetch(PDO::FETCH_NUM)===[7,null],'Positional behavior');binding(lastRecord(),1,7,PDO::PARAM_INT);binding(lastRecord(),2,null,PDO::PARAM_NULL);},
 'positional_execute_array'=>function(){ $d=fixture();$s=$d->prepare('SELECT ?,?');$s->execute([7,'alpha']);need($s->fetch(PDO::FETCH_NUM)===['7','alpha'],'Array PDO string behavior');binding(lastRecord(),1,7,PDO::PARAM_STR);binding(lastRecord(),2,'alpha',PDO::PARAM_STR);},
 'array_replaces_reference'=>function(){ $d=fixture();$s=$d->prepare('SELECT :v');$v='before';$s->bindParam(':v',$v);$s->execute(['v'=>'override']);need($s->fetchColumn()==='override','Override behavior');$v='after';$s->execute();need($s->fetchColumn()==='override','Reference incorrectly restored');binding(lastRecord(),':v','override',PDO::PARAM_STR);},
 'typed_null_bool_empty'=>function(){ $d=fixture();$s=$d->prepare('SELECT :n,:b,:s');$s->bindValue(':n',null,PDO::PARAM_NULL);$s->bindValue(':b',true,PDO::PARAM_BOOL);$s->bindValue(':s','',PDO::PARAM_STR);$s->execute();need($s->fetch(PDO::FETCH_NUM)===[null,1,''],'Typed result changed');$r=lastRecord();binding($r,':n',null,PDO::PARAM_NULL);binding($r,':b',true,PDO::PARAM_BOOL);binding($r,':s','',PDO::PARAM_STR);},
 'failed_execute_preserves_exception'=>function(){ $d=fixture();$d->exec('CREATE TEMPORARY TABLE t(id INTEGER PRIMARY KEY)');$s=$d->prepare('INSERT INTO t VALUES(?)');$s->execute([1]);$caught=false;try{$s->execute([1]);}catch(PDOException){$caught=true;}need($caught,'Original PDO exception swallowed');$r=lastRecord();need($r['success']===false,'Failed attempt not marked');binding($r,1,1,PDO::PARAM_STR);need(($r['error']['sqlstate']??null)==='23000','Failed SQLSTATE missing');},
 'direct_query_once'=>function(){ $d=fixture();DashboardProfile::$queries=[];need((int)$d->query('SELECT 41')->fetchColumn()===41,'query result changed');need(count(DashboardProfile::$queries)===1,'Direct query missing or doubled');need(lastRecord()['operation']==='query','query operation missing');},
 'direct_exec_zero_rows'=>function(){ $d=fixture();DashboardProfile::$queries=[];need($d->exec('CREATE TEMPORARY TABLE t(id INTEGER)')===0,'Zero-row exec changed');need(count(DashboardProfile::$queries)===1,'exec missing or doubled');need(lastRecord()['success']===true&&lastRecord()['operation']==='exec','exec success misclassified');},
 'failed_prepare'=>function(){ $d=fixture();DashboardProfile::$queries=[];$caught=false;try{$d->prepare('SELECT * FROM nonexistent_table');}catch(PDOException){$caught=true;}need($caught,'Prepare exception swallowed');need(lastRecord()['success']===false&&lastRecord()['operation']==='prepare','Prepare failure not captured');},
 'silent_failure'=>function(){ $d=fixture();$d->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_SILENT);DashboardProfile::$queries=[];need($d->exec('INSERT INTO missing_table VALUES(1)')===false,'Silent failure behavior changed');need(lastRecord()['success']===false&&isset(lastRecord()['error']['sqlstate']),'Silent error not recorded');}
];
$out=[];foreach($cases as$name=>$case){DashboardProfile::$queries=[];try{$case();$out[$name]=['status'=>'PASS'];}catch(Throwable $e){$out[$name]=['status'=>'FAIL','reason'=>$e->getMessage()];}}
$failed=array_filter($out,fn($r)=>$r['status']==='FAIL');echo json_encode(['status'=>$failed?'FAIL':'PASS','cases'=>$out],JSON_PRETTY_PRINT|JSON_THROW_ON_ERROR).PHP_EOL;exit($failed?1:0);
